-- Conferência do 06 revisado (R5) — SOMENTE LEITURA (não cria, não altera, não apaga nada)
select 1 as item, 'Versões registradas (00 a 06 e a revisão 06.1)' as verificacao, (select string_agg(versao, ',' order by versao) from app.versoes_esquema where versao <= '06.1') as resultado, '00,01,02,03,04,05,06,06.1' as esperado
union all select 2, 'Colunas novas da auditoria (sessão, aplicação, responsável declarado)', (select string_agg(column_name, ',' order by column_name) from information_schema.columns where table_schema = 'public' and table_name = 'auditoria' and column_name in ('sessao_usuario', 'aplicacao', 'responsavel_declarado')), 'aplicacao,responsavel_declarado,sessao_usuario'
union all select 3, 'Impressão digital inclui os campos novos', (select (prosrc like '%responsavel_declarado%' and prosrc like '%sessao_usuario%')::text from pg_proc where pronamespace = 'app'::regnamespace and proname = 'auditoria_hash'), 'true'
union all select 4, 'Operação direta sem responsável declarado é recusada (MI401)', (select (prosrc like '%MI401%' and prosrc like '%app.responsavel%')::text from pg_proc where pronamespace = 'app'::regnamespace and proname = 'tg_auditoria'), 'true'
union all select 5, 'Registros de auditoria', (select count(*)::text from public.auditoria), '0'
union all select 6, 'Quebras na cadeia', (select count(*)::text from (select a.hash <> app.auditoria_hash(a) or a.hash_anterior is distinct from lag(a.hash) over (order by a.seq) quebra from public.auditoria a) x where quebra), '0'
union all select 7, 'Gatilhos de auditoria nas tabelas de dados (linha / TRUNCATE)', (select count(*) filter (where tgname like '%\_z\_auditoria')::text || ' / ' || count(*) filter (where tgname like '%\_z\_auditoria\_truncate')::text from pg_trigger where not tgisinternal), '16 / 16'
union all select 8, 'Portal ou anônimo com acesso à auditoria (o 07 libera a leitura só ao ADMIN)', (select coalesce(bool_or(has_table_privilege(ro, 'public.auditoria', pr)), false)::text from unnest(array['anon', 'authenticated']) ro, unnest(array['select', 'insert', 'update', 'delete']) pr), 'false'
union all select 9, 'IMPORTANTE — o SQL Editor roda como administrador do banco? (a regra R5 depende disso)', case when session_user in ('postgres', 'supabase_admin') then 'sim (' || session_user || ')' else 'NÃO (' || session_user || ') — pare e me avise' end, 'sim (postgres)'
union all select 10, 'ÂNCORA da auditoria — anotar fora do banco', coalesce((select seq::text || ' | ' || hash from public.auditoria order by seq desc limit 1), 'trilha vazia'), 'anotar'
order by item;
